  gen_random_uuid()::text,
  ra.tenant_id,
  '0',
  'resource_account',
  ra.id,
  ra.id,
  NULL,
  'app_secret',
  oa.app_secret_ref,
  encode(sha256(convert_to(oa.app_secret_ref, 'UTF8')), 'hex'),
  oa.updated_at::text,
  'active',
  ra.maintainer_user_id,
  oa.updated_at::text,
  oa.updated_at::text
FROM iam_user_official_account oa
JOIN iam_oauth_resource_account ra
  ON ra.id = oa.id
